cd /tmp && cat > wtrace.c <<'EOF'
#define _GNU_SOURCE
#include <unistd.h>
#include <dlfcn.h>
#include <stdio.h>
#include <string.h>
static ssize_t (*real_write)(int,const void*,size_t);
ssize_t write(int fd, const void *buf, size_t n){
  if(!real_write) real_write=dlsym(RTLD_NEXT,"write");
  char msg[256]; int L=snprintf(msg,sizeof msg,"[WRITE fd=%d n=%zu]\n",fd,n);
  real_write(2,msg,L);
  return real_write(fd,buf,n);
}
EOF
gcc -shared -fPIC -o /tmp/wtrace.so /tmp/wtrace.c -ldl 2>&1 | head
cat > /tmp/argc0.c <<'EOF'
#include <unistd.h>
int main(int argc,char**argv){ char*e[]={0}; char*a[]={0}; execve(argv[1],a,e); return 99; }
EOF
gcc -o /tmp/argc0 /tmp/argc0.c 2>&1|head
echo built

BIN=/workspace/dataset/test16_executable
A=$(perl -e "print 'http://e.com/'; print 'a' x 131050")
for c in 100 1000 10000 60000; do
 for i in 1 2; do n=$("$BIN" "$A" | head -c $c | wc -c); echo "head -c $c: ps=${PIPESTATUS[0]} got=$n"; done
done
echo "=== FUZZ: 3000 random inputs, check exit!=0 or stderr!=0 or malformed output ==="
perl -e '
srand(1234);
my @cs = map { chr } (1..255);
for my $t (1..3000) {
  my $L = 1 + int(rand(60));
  my $s = join "", map { $cs[int(rand(scalar @cs))] } 1..$L;
  print $s, "\0";
}' > /tmp/fuzz.bin
perl -e '
local $/ = "\0";
open(F,"<","/tmp/fuzz.bin");
my $bad=0; my $n=0;
while (my $s = <F>) { chomp($s); next if $s eq "";
  $n++;
  my $pid = open(my $ph, "-|");
  if (!$pid) { open(STDERR,">","/tmp/fe"); exec("/workspace/dataset/test16_executable", $s); exit 127; }
  local $/; my $out = <$ph>; close($ph); my $rc = $?;
  my $esz = -s "/tmp/fe";
  # validate format
  my $ok = 1;
  $ok = 0 unless defined $out;
  if ($ok) {
    $ok = 0 unless $out =~ /^[01]\n[01]\n[01]\n[01]\n(\d+)\n/;
    my $N = $1;
    if ($ok) {
      my $rest = $out; $rest =~ s/^[01]\n[01]\n[01]\n[01]\n\d+\n//;
      $ok = 0 unless substr($out,-1) eq "\n" || length($out)==0;
      # byte count check
      my @segs;
      # cannot split reliably if segment has \n; just check total bytes vs N-independent
    }
  }
  if ($rc != 0 || $esz != 0 || !$ok) { $bad++; printf("BAD rc=%d err=%d out=%s arg=%s\n",$rc,$esz,unpack("H*",substr($out//"",0,40)),unpack("H*",$s)) if $bad<20; }
}
print "checked=$n bad=$bad\n";
'

BIN=/workspace/dataset/test16_executable
A=$(perl -e "print 'http://e.com'; print '/abc' x 30000")
echo "=== SIGPIPE default ==="
for i in 1 2 3; do "$BIN" "$A" | head -1 >/dev/null; printf 'ps=%s\n' "${PIPESTATUS[0]}"; done
echo "=== SIGPIPE ignored in parent (inherited SIG_IGN) ==="
perl -e '
$SIG{PIPE}="IGNORE";
for my $i (1..3){
  my $pid = fork();
  if(!$pid){ open(STDOUT,"|-","head -1 >/dev/null") or die; exec("/workspace/dataset/test16_executable", $ARGV[0]); }
  waitpid($pid,0); printf("status=%d (exit=%d sig=%d)\n", $?, $?>>8, $?&127);
}' "$A"
echo "=== SIGPIPE ignored, capture truncated output ==="
perl -e '
$SIG{PIPE}="IGNORE";
pipe(my $r, my $w);
my $pid=fork();
if(!$pid){ close($r); open(STDOUT,">&",$w); exec("/workspace/dataset/test16_executable",$ARGV[0]); }
close($w);
my $buf; sysread($r,$buf,10); close($r);
waitpid($pid,0);
printf("read=%s exit=%d sig=%d\n", unpack("H*",$buf), $?>>8, $?&127);
' "$A"
echo "=== closed stdout write count ==="
cd /tmp; cat > g8.cmd <<'EOF'
set confirm off
set pagination off
set height 0
break main
run http://example.com/a/b/c
catch syscall 1
commands
silent
printf "W fd=%d n=%d\n", $rdi, $rdx
continue
end
continue
quit
EOF
timeout 90 gdb -q -x /tmp/g8.cmd /workspace/dataset/test16_executable 0<&- 1>&- 2>/tmp/gerr; grep -cE '^W ' /tmp/gerr 2>/dev/null; echo "gdb-run done"
